// Se queda con los runs fallidos que todavia no se han diagnosticado.
//
// El CI NO entra: tiene su propio camino (`ci-averiado.yml`), que ademas lanza un
// agente que lo arregla. Aqui solo llegan los programados, que casi nunca fallan por
// codigo -un secret que falta, una cuota agotada, una migracion sin aplicar- y para
// los que el aviso actual solo sabe decir «ha fallado».
const estado = $getWorkflowStaticData('global');
estado.vistos = estado.vistos || [];

// Solo lo de las ultimas 24 horas. Sin esto, la primera vuelta encuentra los fallos
// ANTIGUOS que siguen en la lista de GitHub -averias ya resueltas hace meses- y va
// abriendo un issue viejo cada 15 minutos hasta vaciarlos. Descubierto probandolo:
// el primero que salio fue una copia de Supabase de hace semanas.
const limite = Date.now() - 24 * 60 * 60 * 1000;

const runs = ($input.first().json.workflow_runs || [])
  .filter(r => r.name !== 'CI')
  .filter(r => new Date(r.created_at).getTime() > limite)
  .filter(r => !estado.vistos.includes(r.id));

// Tope de uno por vuelta. Si se rompen tres cosas a la vez no queremos tres llamadas
// al modelo y tres issues en el mismo minuto: el resto se cogen en las vueltas
// siguientes, cada 15 minutos.
const run = runs[0];
if (!run) return [];

// Ojo: aqui NO se marca como visto. Se marca al final, en «Redactar el issue». Si se
// marcase aqui y el diagnostico fallase a mitad, la averia se perderia para siempre.
return [{ json: {
  run_id: run.id,
  workflow: run.name,
  url: run.html_url,
  sha: (run.head_sha || '').slice(0, 7),
  fecha: run.created_at,
} }];

// El job que fallo, que es del que interesa el registro. Un run puede tener varios.
const jobs = $input.first().json.jobs || [];
const malo = jobs.find(j => j.conclusion === 'failure') || jobs[0];
const run  = $('¿Alguno sin diagnosticar?').first().json;

// Los pasos con su resultado sirven de respaldo: si el registro no se puede
// descargar, esto solo ya dice bastante.
const pasos = (malo?.steps || [])
  .map(p => (p.conclusion === 'failure' ? 'X ' : '. ') + p.name)
  .join(String.fromCharCode(10));

return [{ json: { ...run, job_id: malo?.id, job: malo?.name, pasos } }];

// El registro de Actions viene con marca de tiempo por linea y codigos de color ANSI,
// y empieza con 30 lineas de preambulo del runner que no dicen nada. Lo que importa
// esta al final, asi que se recortan las ultimas 80 lineas ya limpias.
//
// Esto no es cosmetica: es lo que hace que quepa en una peticion barata y que el
// modelo no se distraiga con la version del runner.
const j = $input.first().json;
const texto = typeof j.data === 'string' ? j.data : (typeof j.body === 'string' ? j.body : '');

const limpio = texto
  .split(String.fromCharCode(10))
  .map(l => l.replace(/^\S+\t\S+\t/, ''))
  .map(l => l.replace(/^\uFEFF/, ''))
  .map(l => l.replace(/^\d{4}-\d{2}-\d{2}T[\d:.]+Z\s?/, ''))
  .map(l => l.replace(/\u001b\[[0-9;]*m/g, ''))
  .filter(l => l.trim())
  .slice(-80)
  .join(String.fromCharCode(10));

const meta = $('Job que ha fallado').first().json;
const log = limpio || meta.pasos || '(sin registro)';

// El prompt se arma aqui, no en la expresion del nodo HTTP: alli sus comillas y sus
// saltos de linea rompen el parser de expresiones de n8n.
const nl = String.fromCharCode(10);
const prompt = [
  'Eres quien diagnostica averias de un proyecto personal. Te doy el final del registro de un workflow de GitHub Actions que ha fallado.',
  '',
  'Responde SOLO con este JSON:',
  '{"causa": "<una sola frase, en espanol, diciendo QUE ha fallado y POR QUE>", "tipo": "<secret|cuota|migracion|codigo|red|otro>", "lo_arregla_un_agente": <true|false>}',
  '',
  'Reglas:',
  '- Si el fallo viene de que un servicio externo respondio mal (502, 503, timeout, DNS), el tipo es «red» y la causa debe decir que el problema NO esta en el workflow sino en ese servicio.',
  '- «lo_arregla_un_agente» solo es true si el arreglo esta en el codigo del repositorio. Un secret que falta, una cuota agotada o una migracion sin aplicar son false: eso lo tiene que tocar una persona.',
  '- Si no puedes saberlo, dilo en la causa. No inventes.',
  '',
  'Workflow: ' + meta.workflow,
  'Registro:',
  log,
].join(nl);

return [{ json: { ...meta, log, prompt } }];

// El texto del modelo viene envuelto en la respuesta de Gemini y, pese al
// responseMimeType, puede traer un bloque de codigo alrededor. Se limpia antes.
const cand = $input.first().json?.candidates?.[0];
let crudo = (cand?.content?.parts?.[0]?.text || '').trim();
crudo = crudo.replace(/^```(?:json)?/, '').replace(/```$/, '').trim();

const fallo = $input.first().json?.error?.message || '';

let d;
try { d = JSON.parse(crudo); }
catch (e) {
  // El plan gratuito de Gemini se satura a ratos y devuelve UNAVAILABLE. Eso no puede
  // costarnos el aviso: sin diagnostico el issue sigue valiendo, porque lleva el
  // registro dentro. Al reves no: un diagnostico sin registro no se puede comprobar.
  d = { causa: fallo
          ? 'No se pudo diagnosticar automaticamente (' + fallo.slice(0, 120) + '). El registro esta abajo.'
          : (crudo.slice(0, 400) || 'El modelo no devolvio nada legible. El registro esta abajo.'),
        tipo: 'otro', lo_arregla_un_agente: false };
}

const meta = $('Limpiar el registro').first().json;
const etiquetas = { secret: 'Falta un secret', cuota: 'Cuota agotada',
                    migracion: 'Migracion sin aplicar', codigo: 'Fallo de codigo',
                    red: 'Servicio externo caido', otro: 'Sin clasificar' };
const etiqueta = etiquetas[d.tipo] || 'Sin clasificar';
const nl = String.fromCharCode(10);

const cuerpo = [
  '**' + d.causa + '**',
  '',
  '- **Tipo**: ' + etiqueta,
  '- **Lo puede arreglar un agente**: ' + (d.lo_arregla_un_agente ? 'si' : 'no, esto lo tienes que tocar tu'),
  '- **Run**: ' + meta.url,
  '- **Sobre**: `' + meta.sha + '`',
  '',
  '<details><summary>Final del registro</summary>',
  '',
  '```',
  meta.log,
  '```',
  '',
  '</details>',
  '',
  '_Diagnostico automatico de n8n con Gemini. Puede equivocarse: el registro de arriba es la fuente._',
].join(nl);

// Se marca como visto ahora, no antes: hemos llegado hasta aqui con algo que contar.
const estado = $getWorkflowStaticData('global');
estado.vistos = [...(estado.vistos || []), meta.run_id].slice(-50);

return [{ json: { titulo: 'Averia: ' + meta.workflow + ' (' + meta.sha + ')', cuerpo } }];
